-- Venue Live Guest "Seminar Virtual". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara seminar), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'seminar', 'Seminar Virtual (webinar)', 'seminar', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 136, 'center 38%',
  $t${"name":"Seminar Virtual","orn":"diamond","ui":{"ivory":"#F2F5FD","white":"#FFFFFF","soft":"#DCE5F8","soft2":"#9DB3E6","accent":"#1F3A93","deep":"#13255F","ink":"#14224F","mute":"#5F6F9C","line":"#CFDAF2","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#F9FAFE","ink":"#14224F","accent":"#1F3A93","gold":"#D9A21B","leaf":"#DCE5F8","hbg":"rgba(242,245,253,.94)","hline":"#9DB3E6","motif":"diamond"},"hud":{"bg":"rgba(19,37,95,.9)","acc":"#FFC94D","on":"#14224F"},"scr":{"wine":"#13255F","veil":"242,245,253"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'seminar');
